(async()=>{let msg='';try{const out={comps:[]};for(const c of await eda.pcb_PrimitiveComponent.getAll()){const id=c.getState_PrimitiveId();const o={des:c.getState_Designator(),x:c.getState_X(),y:c.getState_Y(),r:c.getState_Rotation(),fp:(c.getState_Footprint()||{}).name};try{o.pads=(await eda.pcb_PrimitiveComponent.getAllPinsByPrimitiveId(id)||[]).map(p=>[p.getState_PadNumber(),p.getState_Net()])}catch(e){}out.comps.push(o)}const f=new File([JSON.stringify(out)],'vrb_pcb2.json',{type:'application/json'});await eda.sys_FileSystem.saveFile(f,'vrb_pcb2.json');msg='ok '+out.comps.length}catch(e){msg='ERR '+e}eda.sys_Message.showToastMessage(msg);})();